// GEP 資產工廠
const AssetFactory = {
  build: async function(chainId) {
    const genes = await this.loadGenes(chainId);
    const capsules = await this.loadCapsules(chainId);
    const bundles = [];
    for (const gene of genes) {
      const capsule = this.matchCapsule(gene, capsules);
      const event = this.createEvent(gene, capsule);
      bundles.push({ gene, capsule, event });
    }
    return bundles;
  },
